import{_ as t,o as s,c as a,a2 as r}from"./chunks/framework.DT_qyuxR.js";const m=JSON.parse('{"title":"Phases de jeu","description":"","frontmatter":{},"headers":[],"relativePath":"regles/02-phases.md","filePath":"regles/02-phases.md"}'),o={name:"regles/02-phases.md"};function n(d,e,l,i,u,p){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="phases-de-jeu" tabindex="-1">Phases de jeu <a class="header-anchor" href="#phases-de-jeu" aria-label="Permalink to &quot;Phases de jeu&quot;">​</a></h1><h2 id="le-cycle-complet" tabindex="-1">Le cycle complet <a class="header-anchor" href="#le-cycle-complet" aria-label="Permalink to &quot;Le cycle complet&quot;">​</a></h2><p>Une partie de Carnival of the Deads suit un cycle repete jusqu&#39;a la victoire d&#39;un camp :</p><blockquote><p><strong>Nuit</strong> → <strong>Resolution</strong> → <strong>Debats</strong> → <strong>Actions de Jour</strong> → <strong>Duels</strong> → <em>(cycle suivant)</em></p></blockquote><p>Chaque phase se deroule dans l&#39;ordre ci-dessus. Apres les Duels, un nouveau cycle recommence par la Nuit.</p><h2 id="phase-de-nuit" tabindex="-1">Phase de Nuit <a class="header-anchor" href="#phase-de-nuit" aria-label="Permalink to &quot;Phase de Nuit&quot;">​</a></h2><p><strong>Duree</strong> : illimitee (les joueurs envoient leurs actions en MP au bot)</p><p>C&#39;est la phase la plus secrete du jeu. Chaque joueur recoit en <strong>message prive</strong> les actions disponibles pour son masque :</p><ul><li>Les joueurs ayant une <strong>capacite de Nuit</strong> peuvent l&#39;utiliser maintenant.</li><li>Les joueurs sans capacite de Nuit observent simplement le deroulement.</li><li>Les <strong>deplacements sont verrouilles</strong> : personne ne peut changer de salon vocal.</li><li>Les joueurs sont <strong>muets</strong> dans les salons vocaux.</li></ul><h3 id="ordre-de-resolution" tabindex="-1">Ordre de resolution <a class="header-anchor" href="#ordre-de-resolution" aria-label="Permalink to &quot;Ordre de resolution&quot;">​</a></h3><p>Les actions de Nuit sont resolutes dans un <strong>ordre precis</strong> :</p><table tabindex="0"><thead><tr><th>Ordre</th><th>Masque</th><th>Capacite</th><th>Effet</th></tr></thead><tbody><tr><td>1</td><td>Sans-Visage</td><td>Metamorphose</td><td>Copie le masque de la cible</td></tr><tr><td>1</td><td>Messager</td><td>Passerelle</td><td>Envoie un message anonyme</td></tr><tr><td>2</td><td>Abysse</td><td>Regard Noir</td><td>Inflige Maudit</td></tr><tr><td>3</td><td>Rempart</td><td>Forteresse</td><td>Bouclier (reduit les degats)</td></tr><tr><td>4</td><td>Maestro</td><td>Crescendo</td><td>Degats croissants</td></tr><tr><td>5</td><td>Parasite</td><td>Infestation</td><td>Degats + soin continus</td></tr><tr><td>6</td><td>Vampirisme</td><td>Piqure</td><td>Degats + soin</td></tr><tr><td>7</td><td>Courroux</td><td>Fureur</td><td>Degats de vengeance</td></tr><tr><td>8</td><td>Eclat</td><td>Radiance</td><td>Degats si pas attaque</td></tr><tr><td>9</td><td>Sommeil</td><td>Berceuse</td><td>Inflige Endormi</td></tr><tr><td>10</td><td>Gaz</td><td>Vapeur Nocive</td><td>Degats</td></tr><tr><td>11</td><td>Foudre</td><td>Entraves</td><td>Degats</td></tr><tr><td>12</td><td>Vampire</td><td>Offrande Sanglante</td><td>Soin</td></tr><tr><td>13</td><td>Medium</td><td>Spiritisme</td><td>Decouvre le camp d&#39;un joueur</td></tr><tr><td>14</td><td>Foyer</td><td>Instinct Maternel</td><td>Selectionne un Enfant</td></tr></tbody></table><blockquote><p><strong>Pourquoi cet ordre ?</strong> Il permet des combos et des contres. La Metamorphose est resolue en premier pour que Sans-Visage puisse copier un masque avant que celui-ci ne soit revele par d&#39;autres effets.</p></blockquote><h2 id="phase-de-resolution" tabindex="-1">Phase de Resolution <a class="header-anchor" href="#phase-de-resolution" aria-label="Permalink to &quot;Phase de Resolution&quot;">​</a></h2><p><strong>Duree</strong> : quelques secondes (automatique)</p><p>Le bot resout automatiquement toutes les actions de Nuit dans l&#39;ordre :</p><ul><li>Les degats sont appliques.</li><li>Les soins sont appliques.</li><li>Les effets speciaux (Maudit, Metamorphose, etc.) sont declenches.</li><li>Si un masque se brise, <strong>l&#39;identite du joueur est revelee</strong> dans le salon general.</li><li>Le joueur K.O. peut laisser une <strong>derniere rumeur</strong>.</li></ul><blockquote><p><strong>Important</strong> : la resolution est <strong>publique</strong>. Tout le monde voit les resultats des actions de Nuit (mais pas qui les a effectuees).</p></blockquote><h2 id="phase-de-debats" tabindex="-1">Phase de Debats <a class="header-anchor" href="#phase-de-debats" aria-label="Permalink to &quot;Phase de Debats&quot;">​</a></h2><p><strong>Duree</strong> : 5 minutes (configurable)</p><p>C&#39;est la phase de discussion libre. Les joueurs peuvent :</p><ul><li><strong>Parler</strong> dans les salons vocaux.</li><li><strong>Se deplacer</strong> librement entre les 3 zones du bal.</li><li><strong>Accuser</strong>, <strong>defendre</strong>, <strong>bluffer</strong>, <strong>reseauter</strong>.</li><li>Consulter le <strong>Grimoire des Masques</strong> et leur panneau joueur.</li></ul><p>Aucune action de pouvoir ne peut etre utilisee pendant les Debats. C&#39;est le moment du pur social.</p><h2 id="phase-d-actions-de-jour" tabindex="-1">Phase d&#39;Actions de Jour <a class="header-anchor" href="#phase-d-actions-de-jour" aria-label="Permalink to &quot;Phase d&#39;Actions de Jour&quot;">​</a></h2><p><strong>Duree</strong> : jusqu&#39;a ce que tous les joueurs aient utilise leur capacite de Jour (ou renonce)</p><p>Les joueurs ayant une <strong>capacite de Jour</strong> peuvent l&#39;utiliser maintenant :</p><ul><li>Les actions sont soumises en MP au bot.</li><li>Certains masques ont des actions <strong>immediates</strong> (appliquees tout de suite).</li><li>D&#39;autres ont des actions <strong>differees</strong> (appliquees a la fin de la journee).</li></ul><blockquote><p><strong>Astuce</strong> : si vous n&#39;avez pas de capacite de Jour, vous pouvez simplement attendre que la phase se termine.</p></blockquote><h2 id="phase-de-duels" tabindex="-1">Phase de Duels <a class="header-anchor" href="#phase-de-duels" aria-label="Permalink to &quot;Phase de Duels&quot;">​</a></h2><p><strong>Duree</strong> : illimitee (les joueurs declenchent des duels pendant cette phase)</p><p>C&#39;est la phase d&#39;affrontement direct. Un joueur peut <strong>defier</strong> un autre joueur en Duel :</p><ul><li>Les deux joueurs doivent etre dans le <strong>meme salon vocal</strong>.</li><li>Le defi est envoye au joueur cible (acceptation ou refus).</li><li>Si refuse, le defi est annule (pas de consequence).</li><li>Si accepte, le Duel est resolu <strong>automatiquement a la fin de la phase</strong>.</li></ul><h3 id="resolution-des-duels" tabindex="-1">Resolution des Duels <a class="header-anchor" href="#resolution-des-duels" aria-label="Permalink to &quot;Resolution des Duels&quot;">​</a></h3><p>Quand la phase de Duels se termine, tous les Duels acceptes sont resolus <strong>simultanement</strong> :</p><ol><li>Chaque duo de duellistes s&#39;attaque mutuellement avec son <strong>Attaque de Combat</strong>.</li><li>Les degats sont appliques <strong>en meme temps</strong> (meme si l&#39;un des deux tombe K.O.).</li><li>Si un masque se brise, l&#39;identite est revelee.</li></ol><h3 id="duels-simultanes" tabindex="-1">Duels simultanes <a class="header-anchor" href="#duels-simultanes" aria-label="Permalink to &quot;Duels simultanes&quot;">​</a></h3><p>Il est possible de participer a <strong>plusieurs Duels</strong> lors de la meme phase. Le bot gere automatiquement les Duels multiples.</p><h3 id="degats-de-combat" tabindex="-1">Degats de combat <a class="header-anchor" href="#degats-de-combat" aria-label="Permalink to &quot;Degats de combat&quot;">​</a></h3><p>Les degats de combat sont <strong>fixes</strong> et definis par le masque. Ils ne sont pas modifiables par les statuts.</p><h2 id="cycle-suivant" tabindex="-1">Cycle suivant <a class="header-anchor" href="#cycle-suivant" aria-label="Permalink to &quot;Cycle suivant&quot;">​</a></h2><p>Apres les Duels, un nouveau cycle commence par la Nuit. Le numero de nuit s&#39;incremente automatiquement.</p><h2 id="fin-de-partie" tabindex="-1">Fin de partie <a class="header-anchor" href="#fin-de-partie" aria-label="Permalink to &quot;Fin de partie&quot;">​</a></h2><p>La partie se termine quand <strong>l&#39;un des camps est entierement elimine</strong> :</p><ul><li>Tous les Revenants K.O. → <strong>Victoire des Vivants</strong></li><li>Tous les Vivants K.O. → <strong>Victoire des Revenants</strong></li></ul><p>Apres la victoire, le bot revele la composition complete de la partie (identites et camps de tous les joueurs).</p>',45)])])}const h=t(o,[["render",n]]);export{m as __pageData,h as default};
